def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a :class:`datetime.timedelta` instance
    :return: the total number of seconds represented by the timedelta,
             or ``None`` if ``value`` is ``None`` or not a timedelta.
    """
    if value is None:
        return None
    try:
        return value.total_seconds()
    except AttributeError:
        return None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, datetime.time):
        raise TypeError("Expected a datetime.time instance")
    # Return ISO 8601 time string, including microseconds if present
    if value.microsecond:
        return value.strftime('%H:%M:%S.%f')
    return value.strftime('%H:%M:%S')

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if not hasattr(self, "_keys") or self._keys is None:
        return []
    return list(self._keys)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(key)

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # If no keys are provided, return all values
        if not keys:
            return list(self._items.values())

        # Otherwise, collect the requested values
        result = []
        all_values = list(self._items.values())
        for key in keys:
            if isinstance(key, int):
                # Treat as positional index
                try:
                    result.append(all_values[key])
                except IndexError:
                    raise KeyError(f"Index {key} out of range for values list.")
            else:
                # Treat as dictionary key
                if key in self._items:
                    result.append(self._items[key])
                else:
                    raise KeyError(f"Key {key!r} not found in record.")
        return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no specific keys requested, return all fields
    if not keys:
        return dict(zip(self._keys, self._values))

    result = {}
    for key in keys:
        # Handle integer indexes
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            field_name = self._keys[key]
            result[field_name] = self._values[key]
        else:
            # Treat as a field name
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                # Key not present in the record
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"Field names must be strings: {f!r}")
    namespace = {'__slots__': fields, 'SRID_MAP': srid_map}
    def __init__(self, x, y, *args, **kwargs):
        super(self.__class__, self).__init__(x, y)
        for name, value in zip(fields, args):
            setattr(self, name, value)
        for key, value in kwargs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                raise TypeError(f"Unexpected keyword argument {key!r}")
    namespace['__init__'] = __init__
    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
