def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    # Identify fields that should be copied verbatim when at the top level
    identifying_fields = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process each element of the list
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Non-dict, non-list values are replaced with None, except for
            # identifying fields at the top level
            if first_level and key in identifying_fields:
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic sanity checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Iterate over the schema and corresponding response values
    for idx, schema_item in enumerate(observer_schema):
        # Skip if the response does not contain this index
        if idx >= len(response):
            continue

        # Ensure the last_applied_manifest list is long enough
        if idx >= len(last_applied_manifest):
            # Determine the default value based on the schema type
            if isinstance(schema_item, dict):
                last_applied_manifest.append({})
            elif isinstance(schema_item, list):
                last_applied_manifest.append([])
            else:
                last_applied_manifest.append(None)

        # Retrieve the current value in the manifest
        current_val = last_applied_manifest[idx]
        resp_val = response[idx]

        # Handle nested structures
        if isinstance(schema_item, dict):
            # Ensure we have a dict to work with
            if not isinstance(current_val, dict):
                current_val = {}
                last_applied_manifest[idx] = current_val
            # Recurse into the dict
            update_last_applied_manifest_dict_from_resp(
                current_val, schema_item, resp_val
            )
        elif isinstance(schema_item, list):
            # Ensure we have a list to work with
            if not isinstance(current_val, list):
                current_val = []
                last_applied_manifest[idx] = current_val
            # Recurse into the list
            update_last_applied_manifest_list_from_resp(
                current_val, schema_item, resp_val
            )
        else:
            # Scalar field: initialize if not already set
            if current_val is None:
                # Only set if the response provides a non-None value
                if resp_val is not None:
                    last_applied_manifest[idx] = resp_val
            # If current_val is already set, leave it unchanged
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key!r} not present in response")
        if isinstance(sub_schema, dict):
            # Ensure nested dict exists
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            # Recurse into nested structure
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, response[key]
            )
        else:
            # Only set if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schema attribute exists
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}
