    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return False
    try:
        # Attempt to import the OCFL library
        import ocfl
        # If the path is a pyfs root object, use its underlying path
        if hasattr(path, "path"):
            path = path.path
        # Perform validation
        result = ocfl.validate(path)
        # Interpret the result
        if isinstance(result, bool):
            return result
        if isinstance(result, (list, tuple)):
            # Assume the first element indicates validity
            return bool(result[0])
        return False
    except Exception:
        return False

