def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure manifest_files is a mapping of file -> digest
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    # Check that each digest in the manifest is used
    missing_used = [fname for fname, digest in manifest_files.items() if digest not in digests_used]
    if missing_used:
        raise ValueError(f"Digests for files {', '.join(missing_used)} are not used.")
    # Check that all used digests are present in the manifest
    used_not_in_manifest = set(digests_used) - set(manifest_files.values())
    if used_not_in_manifest:
        raise ValueError(f"Used digests {', '.join(used_not_in_manifest)} not present in manifest.")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Ensure prior is older than the current inventory
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise AttributeError("Both inventories must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(f"prior version ({prior.version}) must be older than current version ({self.version})")

    # Ensure prior inventory is a subset of the current inventory
    if not hasattr(prior, "inventory") or not hasattr(self, "inventory"):
        raise AttributeError("Both inventories must have an 'inventory' attribute")
    for key, prior_val in prior.inventory.items():
        if key not in self.inventory:
            raise ValueError(f"prior contains key {key!r} not present in current inventory")
        current_val = self.inventory[key]
        # If values are numeric, ensure current is not less than prior
        try:
            if current_val < prior_val:
                raise ValueError(f"current inventory value for {key!r} ({current_val}) is less than prior's value ({prior_val})")
        except TypeError:
            # For non-numeric values, just ensure equality
            if current_val != prior_val:
                raise ValueError(f"current inventory value for {key!r} differs from prior's value")

    # Optional: check that constraints (if any) are consistent
    if hasattr(prior, "constraints") and hasattr(self, "constraints"):
        for key, prior_con in prior.constraints.items():
            if key not in self.constraints:
                raise ValueError(f"prior has constraint {key!r} not present in current inventory")
            if self.constraints[key] != prior_con:
                raise ValueError(f"constraint {key!r} differs between prior and current inventory")
    return True

