def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        try:
            import pprint
            attrs = vars(self)
            return f"{self.__class__.__name__}({pprint.pformat(attrs, indent=indent)})"
        except Exception:
            return f"{self.__class__.__name__}({repr(self)})"
    try:
        import json
        return json.dumps(self, default=lambda o: getattr(o, "__dict__", str(o)), indent=indent)
    except Exception:
        try:
            import pprint
            return pprint.pformat(self, indent=indent)
        except Exception:
            return repr(self)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner

