    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Assume the hierarchy is stored in an attribute called _storage_root
    for obj in getattr(self, "_storage_root", []):
        num_objects += 1
        valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                validate_method = getattr(obj, "validate", None)
                if callable(validate_method):
                    # If validate returns False, consider it invalid
                    if not validate_method():
                        valid = False
                # If no validate method, assume the object is valid
            except Exception as e:
                valid = False
                if show_warnings:
                    warnings.warn(f"Validation error for object {obj!r}: {e}")

        # Check digests if requested and the object passed validation
        if check_digests and valid:
            try:
                get_digest = getattr(obj, "get_digest", None)
                compute_digest = getattr(obj, "compute_digest", None)
                if callable(get_digest) and callable(compute_digest):
                    if get_digest() != compute_digest():
                        valid = False
                        if show_warnings:
                            warnings.warn(f"Digest mismatch for object {obj!r}")
                # If digest methods are missing, skip digest check
            except Exception as e:
                valid = False
                if show_warnings:
                    warnings.warn(f"Digest check error for object {obj!r}: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    if not version.isdigit():
        # If the version string contains non-digit characters, return it unchanged.
        return version
    num = int(version) + 1
    if version.startswith("0"):
        # Preserve the original length with leading zeros.
        return str(num).zfill(len(version))
    return str(num)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure required attributes exist
    if not hasattr(self, 'root_inventory'):
        raise AttributeError('root_inventory attribute is required')
    if not hasattr(self, 'inventory_dir'):
        raise AttributeError('inventory_dir attribute is required')

    # Prepare a dict to record differences: {content_path: [versions]}
    self.different_digests = {}

    for ver in version_dirs:
        # Construct the expected inventory file path
        inv_path = os.path.join(self.inventory_dir, ver, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise ValueError(f'Inventory file missing for version {ver!r}: {inv_path}')

        # Load the inventory
        try:
            with open(inv_path, 'r', encoding='utf-8') as fh:
                inventory = json.load(fh)
        except Exception as exc:
            raise ValueError(f'Failed to load inventory for version {ver!r}: {exc}')

        # Validate that every entry in the inventory exists in the root inventory
        for path, digest in inventory.items():
            if path not in self.root_inventory:
                raise ValueError(
                    f'Unknown content {path!r} found in inventory for version {ver!r}'
                )
            root_digest = self.root_inventory[path]
            if digest != root_digest:
                self.different_digests.setdefault(path, []).append(ver)

    return self

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def merge_mapping_nodes(a, b):
        """Recursively merge two MappingNode values."""
        merged = {}
        # Add entries from the first mapping
        for k_node, v_node in a.value:
            merged[k_node.value] = (k_node, v_node)
        # Merge entries from the second mapping
        for k_node, v_node in b.value:
            key = k_node.value
            if key in merged:
                existing_k, existing_v = merged[key]
                if isinstance(v_node, type(a)) and isinstance(existing_v, type(a)):
                    merged_v = merge_mapping_nodes(existing_v, v_node)
                    merged[key] = (existing_k, merged_v)
                else:
                    merged[key] = (existing_k, v_node)
            else:
                merged[key] = (k_node, v_node)
        # Preserve order of first appearance
        return type(a)(tag=a.tag, value=list(merged.values()))

    result = {}
    for k_node, v_node in nodes:
        key = k_node.value
        if key in result:
            existing_k, existing_v = result[key]
            if isinstance(v_node, type(existing_v)) and isinstance(existing_v, type(v_node)):
                merged_v = merge_mapping_nodes(existing_v, v_node)
                result[key] = (existing_k, merged_v)
            else:
                result[key] = (existing_k, v_node)
        else:
            result[key] = (k_node, v_node)
    return list(result.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        for opt in action.option_strings:
            if opt.startswith('-') and opt not in flags:
                flags.append(opt)
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    # Parse global arguments
    global_args, _ = parser.parse_known_args(unparsed_arguments)
    result = {"global": global_args}
    # Find subparsers, if any
    subparsers_action = None
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            subparsers_action = action
            break
    if subparsers_action:
        for name, subparser in subparsers_action.choices.items():
            sub_args, _ = subparser.parse_known_args(unparsed_arguments)
            result[name] = sub_args
    return result

