def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings (e.g., ['-h', '--help'])
        flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # Create a top-level parser.  Subparsers are expected to be added by the caller
    # before this function is invoked.
    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name', required=False)

    # Parse known arguments; unknown arguments are ignored.
    namespace, _ = parser.parse_known_args(unparsed_arguments)

    # Build the result dictionary.  If a subparser was used, use its name as the key;
    # otherwise use "global" to indicate top‑level arguments.
    result = {}
    subparser_name = getattr(namespace, 'subparser_name', None)
    if subparser_name:
        result[subparser_name] = namespace
    else:
        result['global'] = namespace

    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    for key, value in url_args.items():
        placeholder_braces = '{' + key + '}'
        placeholder_colon = ':' + key
        url = url.replace(placeholder_braces, str(value))
        url = url.replace(placeholder_colon, str(value))
    return url

