def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])
    while queue:
        c = queue.pop()
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                queue.add(sub)
    seen.discard(cls)
    return seen

