def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_map = {}
    error_records = []

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.toml':
                cfg = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                cfg = yaml.safe_load(raw)
            elif ext == '.json':
                cfg = json.loads(raw)
            else:
                # Unsupported format, treat as error
                raise ValueError(f'Unsupported file extension: {ext}')
            # Apply overrides if provided
            if overrides:
                if isinstance(cfg, dict):
                    cfg.update(overrides)
                else:
                    # If cfg is not a dict, cannot apply overrides
                    pass
            # Resolve environment variables if requested
            if resolve_env:
                def _resolve(val):
                    if isinstance(val, str):
                        return os.path.expandvars(val)
                    elif isinstance(val, dict):
                        return {k: _resolve(v) for k, v in val.items()}
                    elif isinstance(val, list):
                        return [_resolve(v) for v in val]
                    else:
                        return val
                cfg = _resolve(cfg)
            config_map[fname] = cfg
        except Exception as e:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error parsing configuration file {fname}: {e}',
                args=None,
                exc_info=(type(e), e, e.__traceback__)
            )
            error_records.append(record)

    return config_map, error_records

