def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # If iface is a class, use isinstance/issubclass checks
    if isinstance(iface, type):
        # candidate could be a class or an instance
        if isinstance(candidate, type):
            if not issubclass(candidate, iface):
                raise TypeError(f"{candidate.__name__} does not subclass {iface.__name__}")
        else:
            if not isinstance(candidate, iface):
                raise TypeError(f"{candidate} is not an instance of {iface.__name__}")
    else:
        # Treat iface as a protocol-like object: check that candidate has all public attributes
        required_attrs = [attr for attr in dir(iface) if not attr.startswith('_')]
        for attr in required_attrs:
            if not hasattr(candidate, attr):
                if tentative:
                    continue
                raise AttributeError(f"{candidate} does not provide required attribute {attr}")
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a class")
        # Ensure explicit metaclass is compatible with all base metaclasses
        for base in bases:
            base_meta = type(base)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"metaclass conflict: {explicit_mc} is not a subclass of {base_meta}"
                )
        return explicit_mc

    # No explicit metaclass; determine from bases
    if not bases:
        return type

    # Gather metaclasses of all bases
    metaclasses = [type(base) for base in bases]

    # Find the most derived metaclass
    chosen = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(mc, chosen):
            chosen = mc
        elif not issubclass(chosen, mc):
            raise TypeError(
                f"metaclass conflict: {chosen} and {mc} are not compatible"
            )
    return chosen

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('Cache is empty')
    # Find the key with the lowest frequency
    min_key = min(self._freq, key=lambda k: self._freq[k])
    value = self._cache.pop(min_key)
    self._freq.pop(min_key)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    node = self._tail[2]
    if node is self._head:
        raise KeyError('cache is empty')
    self._remove(node)
    return (node[0], node[1])

