def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a mapping")
    missing = []
    for field in getattr(cls, 'REQUIRED_FIELDS', []):
        if field not in data:
            missing.append(field)
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping")
    required_fields = getattr(cls, 'REQUIRED_FIELDS', [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    resolved = {}

    def _resolve(name, seen):
        if name in resolved:
            return resolved[name]
        if name in seen:
            raise ValueError(f"Circular include detected: {' -> '.join(seen + [name])}")
        seen = seen + [name]
        group = parser_dict.get(name, {})
        # Make a shallow copy to avoid mutating the original
        group_copy = dict(group)
        includes = group_copy.pop('include', [])
        if not isinstance(includes, (list, tuple)):
            includes = [includes]
        merged = {}
        for inc in includes:
            if inc not in parser_dict:
                raise KeyError(f"Included group '{inc}' not found in parser_dict")
            merged.update(_resolve(inc, seen))
        merged.update(group_copy)
        resolved[name] = merged
        return merged

    for key in list(parser_dict.keys()):
        _resolve(key, [])
    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Try to obtain a default value from the spec
        spec_default = None
        if isinstance(self.spec, dict):
            spec_default = self.spec.get(arg.name)
        elif hasattr(self.spec, 'get'):
            try:
                spec_default = self.spec.get(arg.name)
            except Exception:
                spec_default = None
        else:
            spec_default = getattr(self.spec, arg.name, None)

        if spec_default is not None:
            defaults[arg.name] = spec_default
        elif not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # If the argument is a dictionary option, recurse into its scheme
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested

    return defaults

def get_deprecated_args(self):
