def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    command_specs = self._specs.get(command_name)
    if command_specs is None:
        return None
    return command_specs.get(argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required', [])
    for name in required:
        if name not in args or args[name] is None:
            raise InvalidArgumentError(f"Missing required argument: {name}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Get option name; support dict or object with attribute
        name = getattr(opt, 'name', None) or opt.get('name')
        if not name:
            continue
        # Get required_when condition; support dict or attribute
        cond = getattr(opt, 'required_when', None) or opt.get('required_when')
        if not cond:
            continue
        try:
            if callable(cond):
                if cond(args, command_name):
                    required.append(name)
            else:
                # Treat non-callable as a string expression
                if eval(cond, {}, {'args': args, 'command_name': command_name}):
                    required.append(name)
        except Exception:
            # If evaluation fails, ignore this option
            continue
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument definitions from the parsed YAML configuration
    arg_defs = self.parsed_yaml.get('args', {})

    for arg_name, value in args.items():
        # Get the definition for this argument, if any
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            continue

        # The maximum allowed length for this argument
        max_len = arg_def.get('length')
        if max_len is None:
            continue

        # Skip values that do not support len()
        try:
            val_len = len(value)
        except TypeError:
            continue

        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum {max_len}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Retrieve minimum and maximum bounds from the instance
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    if min_val is None or max_val is None:
        raise ValueError("Both 'min' and 'max' attributes must be defined on the instance")

    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of values")

    # Validate each value
    for value in iterator:
        if value < min_val:
            raise ValueError(f"Argument {value!r} is less than minimum {min_val!r}")
        if value > max_val:
            raise ValueError(f"Argument {value!r} is greater than maximum {max_val!r}")

    return args

