def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                vars_dict[item[0]] = item[1]
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
   """
    # Retrieve the type conversion mapping for the given parser, if any.
    parser_def = getattr(self, 'parsers', {}).get(parser_name, {})
    # Iterate over a copy of the items to avoid runtime modification issues.
    for key, val in list(values_dict.items()):
        # If a conversion function is defined for this key, use it.
        if key in parser_def:
            conv = parser_def[key]
            try:
                values_dict[key] = conv(val)
                continue
            except Exception:
                # If conversion fails, fall back to common heuristics below.
                pass
        # Common heuristics for simple type inference when no explicit converter is provided.
        if isinstance(val, str):
            lowered = val.lower()
            if lowered in ('true', 'false'):
                values_dict[key] = lowered == 'true'
            else:
                # Try integer conversion.
                try:
                    values_dict[key] = int(val)
                    continue
                except ValueError:
                    pass
                # Try float conversion.
                try:
                    values_dict[key] = float(val)
                    continue
                except ValueError:
                    pass
    # The function modifies values_dict in place; no explicit return is needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine the spec file (default to plugin.json)
    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_file}")

    # Load the spec
    with open(spec_file, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    root_abs = os.path.abspath(root)
    path_abs = os.path.abspath(path)
    if os.path.commonpath([path_abs, root_abs]) != root_abs:
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    return os.path.relpath(path_abs, root_abs)
